-- Add instructions to the built-in expansion without replacing user records or existing notes.
WITH instructions(name, notes) AS (VALUES
    ('Incline Barbell Bench Press', 'Lower the bar toward the upper chest on an incline bench, then press up with your feet planted.'),
    ('Decline Barbell Bench Press', 'Secure your feet on a decline bench and lower the bar toward the lower chest before pressing.'),
    ('Close-Grip Bench Press', 'Use a roughly shoulder-width grip and let the elbows track close as you lower and press.'),
    ('Dumbbell Bench Press', 'With feet planted on a flat bench, lower the dumbbells beside your chest and press above your shoulders.'),
    ('Incline Dumbbell Bench Press', 'Set the bench to a modest incline. Lower the dumbbells to either side of the upper chest and press up.'),
    ('Decline Dumbbell Bench Press', 'Secure your legs on the decline bench. Lower the dumbbells beside the lower chest and press them up.'),
    ('Dumbbell Floor Press', 'Lie on the floor and lower the weights until your upper arms touch down gently, then press.'),
    ('Dumbbell Fly', 'On a flat bench, open your arms in an arc with softly bent elbows, then bring the weights back above your chest.'),
    ('Incline Dumbbell Fly', 'On an incline bench, keep a slight elbow bend and sweep the weights from the sides to above the upper chest.'),
    ('Cable Fly', 'Set the pulleys around chest height and sweep the handles together with a slight elbow bend.'),
    ('Low-to-High Cable Fly', 'Start with the pulleys low and sweep the handles up and inward to upper-chest height.'),
    ('High-to-Low Cable Fly', 'Start with the pulleys high and sweep the handles down and inward without changing elbow bend much.'),
    ('Pec Deck Fly', 'Set the seat so your arms line up near chest height, then bring the pads or handles together.'),
    ('Machine Chest Press', 'Adjust the seat so the handles start near mid-chest. Keep your back supported as you press.'),
    ('Incline Machine Chest Press', 'Set the seat so the handles start near the upper chest and press along the machine path.'),
    ('Incline Push-Up', 'Place your hands on a stable raised surface and lower your chest toward it while keeping your body straight.'),
    ('Decline Push-Up', 'Set your feet on a stable raised surface and lower your chest toward the floor with your trunk braced.'),
    ('Diamond Push-Up', 'Place your hands close together under your chest and keep your elbows near your sides as you lower.'),
    ('Wide Push-Up', 'Place your hands wider than shoulder width and lower your chest without flaring the elbows straight out.'),
    ('Chest Dip', 'Lean slightly forward on the bars, lower through a comfortable range, and press back up.'),
    ('Bent-Over Barbell Row', 'Hinge forward with your back steady, bring the bar toward your lower ribs, and lower it smoothly.'),
    ('Pendlay Row', 'Start each rep from the floor with your torso nearly horizontal and pull the bar toward your lower chest.'),
    ('T-Bar Row', 'Straddle the bar or machine, hinge at the hips, and draw the handle toward your torso without jerking.'),
    ('Chest-Supported Dumbbell Row', 'Lie face down on an incline bench and pull the dumbbells toward your ribs with your chest supported.'),
    ('Seal Row', 'Lie face down on a raised flat bench, row the weights from a dead hang, and keep your chest down.'),
    ('Renegade Row', 'From a high plank on stable dumbbells, row one weight at a time and resist rotating your hips.'),
    ('Chin-Up', 'Hang from an underhand grip and pull your chest toward the bar without swinging.'),
    ('Neutral-Grip Pull-Up', 'Take a palms-facing grip and drive your elbows down as you pull up.'),
    ('Wide-Grip Pull-Up', 'Use an overhand grip slightly wider than shoulder width and pull without kicking or craning your neck.'),
    ('Weighted Pull-Up', 'Secure the added load and use an overhand grip. Pull smoothly and control the descent.'),
    ('Weighted Chin-Up', 'Secure the added load and use an underhand grip. Keep your torso steady through each rep.'),
    ('Seated Cable Row', 'Sit tall and draw the cable handle toward your waist, then let your arms extend without rounding your back.'),
    ('Single-Arm Cable Row', 'With one hand, draw the handle toward your ribs while keeping your shoulders square.'),
    ('Close-Grip Lat Pulldown', 'Use a close handle and pull it toward your upper chest while keeping your torso steady.'),
    ('Single-Arm Lat Pulldown', 'Pull one high cable handle toward the same-side upper chest without twisting or leaning.'),
    ('Straight-Arm Pulldown', 'With arms nearly straight, sweep the bar from shoulder height to your thighs using your shoulders.'),
    ('Chest-Supported Machine Row', 'Adjust the chest pad, keep your torso supported, and bring the handles back toward your ribs.'),
    ('Assisted Pull-Up', 'Select enough assistance for a controlled rep, then pull up and lower smoothly on the platform.'),
    ('Suspension Row', 'Lean back from firm foot placement and pull your chest toward the handles while keeping your hips aligned.'),
    ('Back Extension', 'Set the pad below your hip crease. Hinge down and rise until your torso lines up with your legs.'),
    ('Seated Dumbbell Shoulder Press', 'Sit upright with the weights at shoulder height, press overhead, and lower with control.'),
    ('Standing Dumbbell Shoulder Press', 'Brace with feet planted and press from shoulder height without arching your lower back.'),
    ('Arnold Press', 'Start with palms facing you and rotate them forward as you press overhead. Reverse on the way down.'),
    ('Dumbbell Lateral Raise', 'Raise the weights out to the sides with softly bent elbows and stop around shoulder height.'),
    ('Dumbbell Front Raise', 'Lift the weights in front to about shoulder height without leaning back or swinging.'),
    ('Dumbbell Reverse Fly', 'Hinge forward and open your arms to the sides while maintaining a slight elbow bend.'),
    ('Cable Lateral Raise', 'Stand beside a low pulley and raise the outer arm out to shoulder height without leaning.'),
    ('Cable Reverse Fly', 'Take the opposite cable handles and sweep your arms outward and back at about shoulder height.'),
    ('Face Pull', 'Pull a high rope toward your face and separate the ends as your elbows move out.'),
    ('Machine Shoulder Press', 'Set the handles near shoulder height and press upward with your back supported.'),
    ('Reverse Pec Deck', 'Face the machine pad and open your arms outward without shrugging or lifting your chest off the pad.'),
    ('Landmine Press', 'Secure the bar in a landmine attachment and press its free end forward and upward from your shoulder.'),
    ('Push Press', 'Dip slightly at the knees with your torso upright, drive through the legs, and finish the press overhead.'),
    ('Pike Push-Up', 'Raise your hips, bend your elbows to lower your head toward the floor, and press back up.'),
    ('Handstand Push-Up', 'From a stable supported handstand, lower through a controlled range and press without resting weight on your head.'),
    ('Dumbbell Shrug', 'Lift your shoulders toward your ears with the weights at your sides and lower without rolling them.'),
    ('Barbell Shrug', 'Hold the bar in front of your thighs, shrug straight up, and lower smoothly.'),
    ('Barbell Curl', 'Keep your upper arms near your sides and curl the bar without rocking your torso.'),
    ('EZ-Bar Curl', 'Use the angled grips that keep your wrists comfortable and curl while keeping your elbows steady.'),
    ('Reverse Curl', 'Take an overhand grip and curl with your wrists aligned and upper arms still.'),
    ('Hammer Curl', 'Keep your palms facing each other as you curl and lower the dumbbells.'),
    ('Incline Dumbbell Curl', 'Sit back on an incline bench, let your arms hang, and curl without bringing your elbows forward.'),
    ('Concentration Curl', 'Brace your upper arm against the inside of your thigh and curl without shifting your shoulder.'),
    ('Cross-Body Hammer Curl', 'Keep a neutral grip and curl each dumbbell toward the opposite shoulder.'),
    ('Dumbbell Preacher Curl', 'Support your upper arm on the preacher pad and lower the weight slowly through a comfortable range.'),
    ('Cable Curl', 'Face a low pulley and curl the handle without letting your elbows drift forward.'),
    ('Bayesian Cable Curl', 'Face away from a low pulley and curl with the working upper arm slightly behind your torso.'),
    ('Rope Hammer Curl', 'Grip the rope with palms facing each other and curl without moving your upper arms.'),
    ('Rope Triceps Pushdown', 'Pin your elbows near your ribs and push the rope down, separating its ends near the bottom.'),
    ('Straight-Bar Triceps Pushdown', 'Keep your elbows close and extend them to press the bar down, then return without moving your shoulders.'),
    ('Overhead Cable Triceps Extension', 'Face away from the pulley with upper arms near your head and straighten your elbows forward.'),
    ('Single-Arm Cable Pushdown', 'Keep the working elbow close to your side and extend it fully under control.'),
    ('Dumbbell Triceps Kickback', 'Hinge forward, hold your upper arm still beside your torso, and straighten your elbow behind you.'),
    ('Overhead Dumbbell Triceps Extension', 'Support the weight overhead and bend your elbows to lower it behind your head before straightening.'),
    ('EZ-Bar Skull Crusher', 'On a bench, bend your elbows to lower the bar toward or just behind your forehead, then extend.'),
    ('Triceps Dip', 'Stay fairly upright on the bars and bend your elbows through a comfortable range before pressing up.'),
    ('Dumbbell Wrist Curl', 'Support your forearm palm up and move the dumbbell by bending at the wrist only.'),
    ('Dumbbell Reverse Wrist Curl', 'Support your forearm palm down and lift the back of your hand without lifting your forearm.'),
    ('Front Squat', 'Rest the bar on the front of your shoulders, keep elbows up, and squat with the whole foot planted.'),
    ('Pause Squat', 'Pause briefly at the bottom while staying braced, then stand without bouncing.'),
    ('Box Squat', 'Sit back to a stable box under control, stay braced on contact, and drive back to standing.'),
    ('Zercher Squat', 'Support the bar in your elbow creases, brace, and squat without letting the load pull you forward.'),
    ('Goblet Squat', 'Hold the weight close to your chest and squat between your hips with feet planted.'),
    ('Dumbbell Bulgarian Split Squat', 'Set your rear foot on a stable bench and lower on the front leg before driving through the front foot.'),
    ('Dumbbell Reverse Lunge', 'Step one foot back with dumbbells at your sides, lower the back knee, and return through the front foot.'),
    ('Dumbbell Walking Lunge', 'Step forward with the weights at your sides, lower into a lunge, then bring the rear leg through.'),
    ('Dumbbell Step-Up', 'Place your whole working foot on a stable step. Drive up through that leg and lower under control.'),
    ('Hack Squat', 'Keep your back supported on the sled pad and control the descent before pushing through your feet.'),
    ('Belt Squat', 'Attach the belt around your hips and squat with your feet planted and your torso steady.'),
    ('Single-Leg Press', 'Keep your hips square against the pad and press with one foot through a comfortable range.'),
    ('Leg Extension', 'Align your knees with the machine pivot and straighten your legs without swinging.'),
    ('Single-Leg Extension', 'Align the working knee with the pivot and extend one leg smoothly against the pad.'),
    ('Bodyweight Squat', 'Sit down between your hips with feet planted and knees tracking with your toes, then stand.'),
    ('Reverse Lunge', 'Step one foot behind you, bend both knees, and push through the front foot to return.'),
    ('Walking Lunge', 'Step forward, lower the back knee toward the floor, then drive through the front leg into the next step.'),
    ('Split Squat', 'Keep your stance fixed and lower your rear knee before standing through your front leg.'),
    ('Pistol Squat', 'Extend one leg in front and squat on the other. Use support or a raised target to control depth if needed.'),
    ('Lateral Lunge', 'Step to one side, sit back over that leg while the other stays long, and push back to center.'),
    ('Jump Squat', 'Make a shallow squat, jump vertically, and land softly before resetting.'),
    ('Wall Sit', 'Slide your back down a wall until your knees are comfortably bent and hold with feet flat.'),
    ('Romanian Deadlift', 'With knees slightly bent, hinge until your hamstrings load, then stand with the bar close.'),
    ('Stiff-Leg Deadlift', 'Hinge with only a small fixed knee bend and stop before your lower back rounds.'),
    ('Good Morning', 'With the bar supported across your upper back, unlock your knees and hinge from your hips before standing.'),
    ('Dumbbell Romanian Deadlift', 'Guide the dumbbells close along your thighs as you hinge, then stand by extending your hips.'),
    ('Single-Leg Dumbbell Romanian Deadlift', 'Hinge on one leg as the other reaches back, keeping your hips square and the weights close.'),
    ('Seated Leg Curl', 'Align your knees with the machine pivot, hold your thighs down with the pad, and curl your heels back.'),
    ('Lying Leg Curl', 'Lie face down with knees aligned to the machine pivot and curl your heels toward your glutes.'),
    ('Standing Leg Curl', 'Brace against the standing machine and curl one heel up without moving your thigh.'),
    ('Nordic Hamstring Curl', 'Anchor your ankles, lower from your knees with hips extended, and use your hands to assist the return if needed.'),
    ('Barbell Hip Thrust', 'Support your upper back on a bench and pad the bar across your hips. Drive through your feet to lift it.'),
    ('Barbell Glute Bridge', 'Lie on the floor with the padded bar over your hips and lift them by pressing through your feet.'),
    ('Sumo Deadlift', 'Take a wide stance with toes turned out, grip the bar inside your knees, and push the floor away.'),
    ('Glute Bridge', 'Lie on your back with knees bent and lift your hips until your torso and thighs align.'),
    ('Single-Leg Glute Bridge', 'Keep one foot planted and lift your hips with that leg while keeping your pelvis level.'),
    ('Frog Pump', 'Bring the soles of your feet together and press them together as you lift and lower your hips.'),
    ('Cable Pull-Through', 'Face away from a low pulley with the rope between your legs. Hinge back and stand by extending your hips.'),
    ('Cable Glute Kickback', 'Attach a low cable to your ankle and move that leg behind you without arching your lower back.'),
    ('Kettlebell Swing', 'Hinge to guide the bell back between your legs and snap your hips forward to float it to chest height.'),
    ('Lateral Band Walk', 'Keep tension on the band and take small sideways steps with your hips back and knees over toes.'),
    ('Banded Clamshell', 'Lie on your side with knees bent and feet together. Open your top knee without rolling your pelvis back.'),
    ('Hip Abduction', 'Sit with hips steady and press your knees outward against the pads, then return slowly.'),
    ('Hip Adduction', 'Keep your pelvis supported and bring your thighs together against the pads before returning slowly.'),
    ('Standing Calf Raise', 'With knees nearly straight, lower your heels through a comfortable stretch and rise onto the balls of your feet.'),
    ('Seated Calf Raise', 'Keep knees bent under the pad and raise and lower your heels through a comfortable range.'),
    ('Leg Press Calf Raise', 'Set the balls of your feet securely on the platform and move through the ankles with a slight knee bend.'),
    ('Single-Leg Calf Raise', 'Stand on one foot, use light support for balance, and raise and lower your heel under control.'),
    ('Crunch', 'Curl your ribs toward your pelvis until the shoulder blades lift slightly, then lower without pulling your neck.'),
    ('Reverse Crunch', 'Bring bent knees toward your chest and curl your pelvis gently off the floor before lowering.'),
    ('Bicycle Crunch', 'Turn your ribs toward the opposite bent knee as the other leg extends, then switch sides.'),
    ('Dead Bug', 'Keep your ribs down and lower opposite arm and leg only as far as you can without arching your back.'),
    ('Mountain Climber', 'From a high plank, alternate driving each knee forward while keeping your hips steady.'),
    ('Flutter Kick', 'Keep your lower back supported and alternate small kicks with straight or slightly bent legs.'),
    ('Bird Dog', 'From hands and knees, reach opposite arm and leg long without rotating your trunk.'),
    ('Plank Shoulder Tap', 'From a high plank, alternate tapping the opposite shoulder and keep your hips square.'),
    ('Side Plank', 'Stack your elbow below your shoulder and lift your hips so your body forms a straight line.'),
    ('Hollow Body Hold', 'Lift your shoulders and extend your legs only as far as you can keep your lower back on the floor.'),
    ('Bear Plank', 'From hands and knees, tuck your toes and hover your knees just off the floor without rounding your back.'),
    ('Hanging Knee Raise', 'Hang without swinging and lift bent knees by curling your pelvis toward your ribs.'),
    ('Hanging Leg Raise', 'From a steady hang, raise your legs as far as you can without swinging and lower slowly.'),
    ('Toes-to-Bar', 'Start from a controlled hang, bring your toes toward the bar, and lower before resetting.'),
    ('Cable Crunch', 'Kneel below the high pulley and curl your ribs toward your pelvis without pulling with your arms.'),
    ('Cable Wood Chop', 'With both hands on the cable, sweep diagonally across your body and let your hips turn with your trunk.'),
    ('Pallof Press', 'Stand side-on to the pulley and press the handle straight out while resisting rotation.'),
    ('Ab Wheel Rollout', 'From your knees, roll forward while braced and stop before your lower back arches.'),
    ('Turkish Get-Up', 'Keep the bell stacked over your shoulder as you move from lying to standing through an elbow support, bridge, and lunge. Reverse the sequence.'),
    ('Walking', 'Walk at a steady pace with relaxed shoulders and record time and distance.'),
    ('Incline Walking', 'Set or choose a manageable incline and shorten your stride enough to walk upright without leaning on the rails.'),
    ('Hiking', 'Choose a route suited to your footing and pace. Take shorter controlled steps on steep descents.'),
    ('Cycling', 'Adjust the saddle so the knee stays slightly bent at the bottom of the stroke and pedal smoothly.'),
    ('Rowing Ergometer', 'Push first with your legs, then open your hips and pull the handle. On the return, extend the arms before bending the knees.'),
    ('Elliptical', 'Keep your feet on the pedals and move smoothly with your torso upright.'),
    ('Stair Climber', 'Use full, steady steps with an upright posture and light contact on the rails if needed.'),
    ('Jump Rope', 'Turn the rope mainly with your wrists and jump just high enough to clear it, landing softly.'),
    ('Burpee', 'Place your hands down, move your feet back to a plank, return them under you, and stand or jump.'),
    ('Swimming', 'Use a comfortable stroke and steady breathing, and record the total distance and elapsed time.'),
    ('Ski Ergometer', 'Start the pull by bracing and hinging forward, then drive the handles down past your hips before recovering.'),
    ('Box Jump', 'Jump onto a stable box, land softly with both feet fully on top, and step down to reset.'),
    ('Step-Up', 'Place your whole working foot on the box, drive up through that leg, and step back down slowly.')
)
UPDATE exercises
SET notes = instructions.notes
FROM instructions
WHERE exercises.name = instructions.name AND built_in = 1 AND trim(exercises.notes) = '';

UPDATE exercises
SET notes = 'Start at a comfortable pace, keep your shoulders relaxed, and record elapsed time and distance.'
WHERE name = 'Running' AND built_in = 1 AND (trim(notes) = '' OR notes = 'Record elapsed time and distance.');

UPDATE exercises
SET secondary_muscles = CASE name
    WHEN 'Cable Wood Chop' THEN 'Shoulders, glutes'
    WHEN 'Pallof Press' THEN 'Shoulders, glutes'
    WHEN 'Lateral Band Walk' THEN 'Quadriceps'
    ELSE 'No major secondary muscles'
END
WHERE built_in = 1 AND trim(secondary_muscles) = '';
